#include "rxt_private.h"
#include "dbg.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

#define string "\r\n" "rxt "

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean rxt_set_runtime (UInt8 runtime)
{
	if(runtime <= RXT_MAX_RUNTIME && runtime >= RXT_MIN_RUNTIME)
	{
		rxt.default_runtime = runtime ;

		#if DBG_RXT == 1
		  dbg_tx_text (string) ;
		  dbg_tx_text ("runtime updated to:") ;
		  dbg_tx_u(runtime, 2) ;
		  dbg_tx_text (" min") ;
		#endif

		return TRUE ;
	}
	else
	{
		return FALSE ;
	}
}

